def first_non_repeating_character(s):
    """
    Find the first non-repeated character in a given string.

    Args:
    s (str): The input string to search.

    Returns:
    char/None: The first non-repeated character if found, otherwise None.
    """
    # Create a dictionary to store the count of each character
    char_count = {}

    # Iterate over the string to populate the dictionary with character counts
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate over the string again to find the first non-repeated character
    for char in s:
        if char_count[char] == 1:
            return char

    # If no non-repeated character is found, return None
    return None

def find_solution(a, b, n):
    """
    Finds integers x and y that satisfy the equation ax + by = n.

    Parameters:
    a (int): Coefficient of x.
    b (int): Coefficient of y.
    n (int): The target value.

    Returns:
    tuple: A tuple (x, y) if a solution exists, otherwise None.
    """
    if n % gcd(a, b) != 0:
        return None

    for x in range(n // a + 1):
        if (n - x * a) % b == 0:
            y = (n - x * a) // b
            return (x, y)

    return None

# Helper function to calculate the greatest common divisor (GCD)
def gcd(x, y):
    while y:
        (x, y) = (y, x % y)
    return x

def largest_subset(nums):
    """
    Find the size of the largest subset of a list of numbers so that every pair is divisible.

    :param nums: List of integers
    :return: Size of the largest subset
    """
    if not nums:
        return 0

    nums.sort()
    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] % nums[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

