def freq_count(lst):
    """
    Returns a dictionary with the frequency of all elements in the given list.

    Args:
    lst (list): The list of elements to count frequencies for.

    Returns:
    dict: A dictionary where keys are the elements from the list and values are their frequencies.
    """
    freq_dict = {}
    for item in lst:
        if item in freq_dict:
            freq_dict[item] += 1
        else:
            freq_dict[item] = 1
    return freq_dict

