def remove_Occ(s, ch):
    # Initialize variables to track the first and last occurrence indices
    first_occurrence = -1
    last_occurrence = -1

    # Iterate through the string to find the first and last occurrence of the character
    for i in range(len(s)):
        if s[i] == ch:
            if first_occurrence == -1:
                first_occurrence = i
            last_occurrence = i

    # If the character is not found, return the original string
    if first_occurrence == -1:
        return s

    # Create a new string without the first and last occurrence of the character
    new_string = s[:first_occurrence] + s[first_occurrence + 1:last_occurrence] + s[last_occurrence + 1:]

    return new_string

def is_samepatterns(colors, patterns):
    """
    Check if the given colors follow the same sequence as the patterns.

    Args:
    colors (list of str): The list of colors.
    patterns (list of str): The list of patterns.

    Returns:
    bool: True if the colors follow the same sequence as the patterns, False otherwise.
    """
    # Check if both lists are empty
    if not colors and not patterns:
        return True

    # Check if one of the lists is empty while the other is not
    if not colors or not patterns:
        return False

    # Check if the lengths of the lists are different
    if len(colors) != len(patterns):
        return False

    # Create a dictionary to map each unique pattern to its corresponding color
    pattern_to_color = {}
    for color, pattern in zip(colors, patterns):
        if pattern not in pattern_to_color:
            pattern_to_color[pattern] = color
        elif pattern_to_color[pattern] != color:
            return False

    return True

def is_majority(arr, n, x):
    """
    Check if x is the majority element in the sorted array arr of length n.

    Args:
    arr (list of int): The sorted array.
    n (int): The length of the array.
    x (int): The element to check for majority.

    Returns:
    bool: True if x is the majority element, False otherwise.
    """
    # Helper function to find the first occurrence of x in arr
    def find_first(arr, low, high, x):
        if high >= low:
            mid = (low + high) // 2
            if (mid == 0 or x > arr[mid - 1]) and (arr[mid] == x):
                return mid
            elif x > arr[mid]:
                return find_first(arr, (mid + 1), high, x)
            else:
                return find_first(arr, low, (mid - 1), x)
        return -1

    # Find the first occurrence of x
    first_occurrence = find_first(arr, 0, n - 1, x)

    # If x is not present, return False
    if first_occurrence == -1:
        return False

    # Check if x is the majority element
    if ((first_occurrence + n // 2) < n and arr[first_occurrence + n // 2] == x):
        return True
    return False

